struct Node { public int G, Opened, Closed; }

Node[] nodes = new Node[0];
long[] heap = new long[0];
int search;

void BeginSearch(int cells) {
    if (nodes.Length < cells) { nodes = new Node[cells]; heap = new long[8 * cells + 1]; }
    search++;                                   // все прошлые пометки устарели
}

// f, затем h (ничья — ближе к цели), затем клетка
static long Key(int f, int h, int cell) => ((long)f << 40) | ((long)h << 20) | (long)cell;
// Чебышёв до правого нижнего угла
static int H(int cell, int n) => Math.Max(n - 1 - cell / n, n - 1 - cell % n);

